"""``StratagemTacticsEnv``: any map generated by StratagemDSL as a sc2te_env / SMAC task.

    from smac.env.sc2_tactics.stratagem import StratagemTacticsEnv
    env = StratagemTacticsEnv("build/sc2te/dhls_18_enter_signal/dhls_18_enter_signal.sc2te.json")
    obs, state = env.reset()
    reward, terminated, info = env.step([1] * env.n_agents)

It is a subclass of sc2te's ``SC2TacticsEnv`` and keeps its interface (and its
``(reward, delta_enemy, delta_deaths, delta_ally)`` reward tuple unless
``reward_tuple=False``), but everything map specific comes from the spec that
``tools/strat2sc2te.py`` writes, so no per-map registry entry or ``star36env_*``
class is needed.

Differences from the hand-written sc2te maps
--------------------------------------------
* agents = units of the strategy's allied *forces*; allied *assets* (bases,
  pylons ...) are extra rows in the ally block of obs/state; enemies = all
  units of all enemy forces and assets (plus empty slots for forces the plan
  spawns later).
* win / loss = the strategy's ``intent { success ...; failure ... }`` evaluated
  on the raw observation every step (``termination="intent"``); alternatives:
  ``"plan"`` (tracked plan reaches a terminal phase, needs StratagemDSL) and
  ``"army"`` (SMAC rule: one side has no units left). Maps packed with
  ``--gameover`` additionally end on the game's own result.
* action space: no-op, stop, 4 moves, *move to each named region* of the
  strategy (``region_actions``), *attack-move to each enemy force/asset*
  (``force_actions``), optional ability actions, attack each enemy slot.
* reset: generated maps respawn the round when players 1 and 2 have no unit
  left (``gt_Reset``), the same mechanism as SMAC maps; the env kills every
  unit of both players (not only the tracked ones) and waits for fresh tags.
  ``--gameover`` maps are restarted with ``RequestRestartGame``.
"""
from __future__ import annotations

import math
from typing import Optional, Sequence, Union

import numpy as np
from absl import logging

from pysc2.lib import protocol
from s2clientprotocol import common_pb2 as sc_common
from s2clientprotocol import debug_pb2 as d_pb
from s2clientprotocol import raw_pb2 as r_pb
from s2clientprotocol import sc2api_pb2 as sc_pb

from smac.env.sc2_tactics.sc2_tactics_env import SC2TacticsEnv, difficulties, races
from smac.env.sc2_tactics.utils import common_utils

from . import conditions, maps
from .spec import ScenarioSpec, resolve_unit_type
from .tracker import UnitTracker

ABILITY = {"move": 16, "attack": 23, "stop": 4, "hold": 18}

# ready-made ability actions: ability_actions=["burrow_down", "burrow_up", {"name": ..., ...}]
ABILITY_PRESETS = {
    "burrow_down": {"ability_id": 3661, "target": "quick",
                    "unit_types": ["Zergling", "Roach", "Hydralisk", "Infestor", "Drone", "Baneling", "Queen",
                                   "Ravager", "Ultralisk", "SwarmHostMP", "LurkerMP"]},
    "burrow_up": {"ability_id": 3662, "target": "quick",
                  "unit_types": ["ZerglingBurrowed", "RoachBurrowed", "HydraliskBurrowed", "InfestorBurrowed",
                                 "DroneBurrowed", "BanelingBurrowed", "QueenBurrowed", "RavagerBurrowed",
                                 "UltraliskBurrowed", "SwarmHostBurrowedMP", "LurkerMPBurrowed"]},
    "siege": {"ability_id": 388, "target": "quick", "unit_types": ["SiegeTank"]},
    "unsiege": {"ability_id": 390, "target": "quick", "unit_types": ["SiegeTankSieged"]},
    "depot_lower": {"ability_id": 556, "target": "quick", "unit_types": ["SupplyDepot"]},
    "depot_raise": {"ability_id": 558, "target": "quick", "unit_types": ["SupplyDepotLowered"]},
    "stim": {"ability_id": 3675, "target": "quick", "unit_types": ["Marine", "Marauder"], "cooldown_steps": 30},
    "heal": {"ability_id": 386, "target": "ally", "unit_types": ["Medivac"], "range": 4},
    "neural_parasite": {"ability_id": 249, "target": "enemy", "unit_types": ["Infestor"], "range": 7,
                        "energy": 100},
    "guardian_shield": {"ability_id": 76, "target": "quick", "unit_types": ["Sentry"], "energy": 75},
    "warp_prism_phasing": {"ability_id": 1528, "target": "quick", "unit_types": ["WarpPrism"]},
    "warp_prism_transport": {"ability_id": 1530, "target": "quick", "unit_types": ["WarpPrismPhasing"]},
}

PLAYER_RESULT = {sc_pb.Victory: 1, sc_pb.Defeat: -1, sc_pb.Tie: 0}


class StratagemTacticsEnv(SC2TacticsEnv):
    def __init__(
        self,
        scenario: Union[str, dict, ScenarioSpec] = None,
        map_name: Optional[str] = None,
        step_mul: Optional[int] = None,
        episode_limit: Optional[int] = None,
        move_amount=2,
        difficulty="1",
        game_version=None,
        seed=None,
        continuing_episode=False,
        obs_all_health=True,
        obs_own_health=True,
        obs_last_action=False,
        obs_pathing_grid=False,
        obs_terrain_height=False,
        obs_instead_of_state=False,
        obs_timestep_number=False,
        obs_own_position=True,
        obs_regions=True,
        obs_plan_phase=False,
        state_last_action=True,
        state_timestep_number=False,
        state_plan_phase=False,
        region_actions=True,
        region_action="move",
        force_actions=True,
        info_detail=False,
        ability_actions: Optional[Sequence] = None,
        min_shoot_range=6.0,
        reward_sparse=False,
        reward_only_positive=True,
        reward_death_value=10,
        reward_win=200,
        reward_defeat=0,
        reward_negative_scale=0.5,
        reward_scale=True,
        reward_scale_rate=20,
        reward_phase=0.0,
        reward_tuple=True,
        termination="intent",
        defeat_on_army_loss=True,
        failure_first=True,
        plan_tracking="auto",
        engine="sc2",
        install_map=True,
        max_reset_tries=12,
        replay_dir="",
        replay_prefix="",
        window_size_x=1920,
        window_size_y=1200,
        heuristic_ai=False,
        heuristic_rest=False,
        debug=False,
        spec=None,
        **unused,
    ):
        """
        scenario       path to ``<stem>.sc2te.json`` (or its folder, a dict, a ScenarioSpec);
                       ``spec=`` is an alias (handy in PyMARL yaml)
        map_name       name under which the map is registered (default ``strat_<stem>``)
        step_mul / episode_limit   default to the spec's ``env`` block
        obs_regions    per agent: relative offset to every named region and "inside" flag
        obs_own_position   own x, y normalised by the map size
        region_actions one action per named region ("move" there, or "attack"-move with region_action="attack")
        force_actions  one action per enemy force/asset: attack-move to the centre of its live units
                       (the DSL's attack(force, target)); available while the target is alive
        ability_actions    list of preset names (see ABILITY_PRESETS) or dicts
                       {"name", "ability_id", "target": quick|enemy|ally, "unit_types": [...],
                        "range", "energy", "cooldown_steps"}
        min_shoot_range    an enemy is attackable within max(weapon range + radii, min_shoot_range);
                       6 is SMAC's fixed range (units walk to the target)
        reward_phase   shaping bonus when the tracked plan enters a new phase (needs StratagemDSL)
        info_detail    put events / outcome / plan phases (lists, strings) into step's info; off by default
                       because PyMARL sums every info value (they are always in env.last_detail)
        reward_tuple   True: step returns ((r, delta_enemy, delta_deaths, delta_ally), done, info) like
                       sc2te's SC2TacticsEnv; False: (r, done, info) like SMAC
        termination    intent | plan | army (see module docstring)
        defeat_on_army_loss  all agents dead (and none still to come) is a defeat
        failure_first  if success and failure hold in the same step, count it as failure
        plan_tracking  auto (when StratagemDSL is importable) | on | off
        engine         sc2 (StarCraft II through PySC2) | fake (StratagemDSL's PlanSim behind the
                       same protocol calls; no SC2 needed, for debugging the pipeline)
        install_map    copy the map to $SC2PATH/Maps/Stratagem_Maps (else used from its absolute path)
        difficulty     built-in AI of player 2, default "1" (VeryEasy): the map script commands the enemy,
                       a stronger AI may give its own orders and break the stratagem (sc2te uses "7")
        """
        scenario = scenario if scenario is not None else spec
        if scenario is None:
            raise ValueError("StratagemTacticsEnv needs scenario=<path to *.sc2te.json>")
        self.spec = scenario if isinstance(scenario, ScenarioSpec) else ScenarioSpec.load(scenario, game_version)
        if unused:
            logging.info("StratagemTacticsEnv ignores %s", sorted(unused))
        self.engine = engine
        name = maps.register(self.spec, map_name, limit=episode_limit, install=install_map,
                             pysc2_map=(engine == "sc2"))
        step_mul = int(step_mul or self.spec.env.get("step_mul") or 8)
        super().__init__(
            map_name=name, step_mul=step_mul, move_amount=move_amount, difficulty=difficulty,
            game_version=game_version, seed=seed, continuing_episode=continuing_episode,
            obs_all_health=obs_all_health, obs_own_health=obs_own_health, obs_last_action=obs_last_action,
            obs_pathing_grid=obs_pathing_grid, obs_terrain_height=obs_terrain_height,
            obs_instead_of_state=obs_instead_of_state, obs_timestep_number=obs_timestep_number,
            state_last_action=state_last_action, state_timestep_number=state_timestep_number,
            reward_sparse=reward_sparse, reward_only_positive=reward_only_positive,
            reward_death_value=reward_death_value, reward_win=reward_win, reward_defeat=reward_defeat,
            reward_negative_scale=reward_negative_scale, reward_scale=reward_scale,
            reward_scale_rate=reward_scale_rate, replay_dir=replay_dir, replay_prefix=replay_prefix,
            window_size_x=window_size_x, window_size_y=window_size_y, heuristic_ai=False,
            heuristic_rest=False, debug=debug)
        if heuristic_ai:
            logging.warning("heuristic_ai is not supported by StratagemTacticsEnv; ignored")

        self.n_ally_assets = self.spec.n_ally_assets
        self.n_regions = len(self.spec.regions)
        self.obs_own_position = obs_own_position
        self.obs_regions = obs_regions and self.n_regions > 0
        self.region_actions = region_actions and self.n_regions > 0
        if region_action not in ("move", "attack"):
            raise ValueError("region_action must be 'move' or 'attack'")
        self.region_action = region_action
        self.enemy_force_names = [f.name for f in self.spec.enemy_forces]
        self.force_actions = force_actions and bool(self.enemy_force_names)
        self.min_shoot_range = float(min_shoot_range)
        self.reward_phase = float(reward_phase)
        self.reward_tuple = reward_tuple
        self.info_detail = info_detail
        self.last_detail = {}
        if termination not in ("intent", "plan", "army"):
            raise ValueError("termination must be intent, plan or army")
        self.termination = termination
        self.defeat_on_army_loss = defeat_on_army_loss
        self.failure_first = failure_first
        self.install_map = install_map
        self.max_reset_tries = max_reset_tries

        # shields: any side with Protoss units (spec race) has a shield feature
        self.shield_bits_ally = 1 if self.spec.races.get("ally") == "P" else 0
        self.shield_bits_enemy = 1 if self.spec.races.get("enemy") == "P" else 0
        self.unit_type_bits = len(self.spec.families)
        self.ally_state_attr_names, self.enemy_state_attr_names = common_utils.initialize_state_attr_names(
            self.shield_bits_ally, self.shield_bits_enemy, self.unit_type_bits)

        # plan tracking (optional)
        from . import plan as plan_mod
        want = plan_tracking == "on" or (plan_tracking == "auto" and plan_mod.available()) \
            or termination == "plan" or reward_phase or obs_plan_phase or state_plan_phase
        if plan_tracking == "off":
            want = False
        if want and not plan_mod.available():
            raise RuntimeError("plan tracking (termination='plan', reward_phase, *_plan_phase) needs StratagemDSL: "
                               "pip install -e StratagemDSL-RL")
        self.plan = plan_mod.PlanProgress(self.spec) if want else None
        self.n_phases = len(self.spec.phase_ids) if self.plan is not None else 0
        self.obs_plan_phase = bool(obs_plan_phase and self.plan is not None)
        self.state_plan_phase = bool(state_plan_phase and self.plan is not None)

        self.tracker = UnitTracker(self.spec)
        self.tracker.plan = self.plan
        bad = conditions.unsupported_calls([self.spec.intent.get("success"), self.spec.intent.get("failure")],
                                           self.spec.derived)
        if bad:
            logging.warning("intent uses %s: evaluated as unknown (never ends an episode)", sorted(bad))

        self._build_actions(ability_actions or [])
        self.last_action = np.zeros((self.n_agents, self.n_actions))
        self.max_reward = self.n_enemies * self.reward_death_value + self.reward_win
        self._max_reward_ready = False
        self._ability_cooldown = {}
        self._game_ended = False
        self._last_outcome = None
        self.agents, self.enemies, self.ally_assets = {}, {}, {}

    # ================================================================ actions
    def _build_actions(self, ability_actions) -> None:
        abilities = []
        for a in ability_actions:
            if isinstance(a, str):
                if a not in ABILITY_PRESETS:
                    raise ValueError(f"unknown ability preset {a!r}; known: {sorted(ABILITY_PRESETS)}")
                d = dict(ABILITY_PRESETS[a], name=a)
            else:
                d = dict(a)
                d.setdefault("name", f"ability_{d['ability_id']}")
            d.setdefault("target", "quick")
            if d["target"] not in ("quick", "enemy", "ally"):
                raise ValueError(f"ability {d['name']}: target must be quick, enemy or ally")
            ids = set()
            for n in d.get("unit_types") or []:
                tid = resolve_unit_type(n, self.game_version)
                if tid is not None:
                    ids.add(tid)
            d["_type_ids"] = ids
            abilities.append(d)
        self.abilities = abilities
        layout = [("noop", None), ("stop", None), ("move", 0), ("move", 1), ("move", 2), ("move", 3)]
        if self.region_actions:
            layout += [("region", i) for i in range(self.n_regions)]
        if self.force_actions:
            layout += [("force", n) for n in self.enemy_force_names]
        layout += [("ability", (k, None)) for k, a in enumerate(abilities) if a["target"] == "quick"]
        self.n_actions_no_attack = len(layout)
        layout += [("attack", e) for e in range(self.n_enemies)]
        for k, a in enumerate(abilities):
            if a["target"] == "enemy":
                layout += [("ability", (k, ("enemy", e))) for e in range(self.n_enemies)]
            elif a["target"] == "ally":
                layout += [("ability", (k, ("ally", i))) for i in range(self.n_agents)]
        self.action_layout = layout
        self.n_actions = len(layout)
        self.n_actions_move = 4

    def get_action_names(self) -> list[str]:
        names = []
        for kind, arg in self.action_layout:
            if kind == "move":
                names.append(["move_north", "move_south", "move_east", "move_west"][arg])
            elif kind == "region":
                names.append(f"{self.region_action}_to:{self.spec.regions[arg].name}")
            elif kind == "force":
                names.append(f"attack_force:{arg}")
            elif kind == "attack":
                names.append(f"attack:enemy_{arg}")
            elif kind == "ability":
                k, tgt = arg
                names.append(self.abilities[k]["name"] + (f":{tgt[0]}_{tgt[1]}" if tgt else ""))
            else:
                names.append(kind)
        return names

    def _stats(self, unit) -> dict:
        return self.spec.stats(unit.unit_type)

    def _is_mobile(self, unit) -> bool:
        st = self._stats(unit)
        if st:
            return not st.get("structure") and st.get("speed", 1.0) > 0
        return True

    def unit_shoot_range(self, agent_id, target=None):
        unit = self.agents.get(agent_id)
        if unit is None:
            return self.min_shoot_range
        st = self._stats(unit)
        if target is None:
            return max(self.min_shoot_range, st.get("range_ground", 0.0)) if st else self.min_shoot_range
        rng = st.get("range_air" if target.is_flying else "range_ground", None) if st else None
        if rng is None:
            return self.min_shoot_range
        if rng <= 0:
            return -1.0           # cannot hit this kind of target at all
        tst = self.spec.stats(target.unit_type)
        reach = rng + st.get("radius", 0.5) + (tst.get("radius", 0.5) if tst else 0.5)
        return max(self.min_shoot_range, reach)

    def unit_sight_range(self, agent_id):
        unit = self.agents.get(agent_id)
        st = self._stats(unit) if unit is not None else {}
        return float(st.get("sight", 9.0)) if st else 9.0

    def get_avail_agent_actions(self, agent_id):
        unit = self.agents.get(agent_id)
        if unit is None or unit.health <= 0:
            return [1] + [0] * (self.n_actions - 1)
        avail = [0] * self.n_actions
        avail[1] = 1
        mobile = self._is_mobile(unit)
        for i, (kind, arg) in enumerate(self.action_layout):
            if kind == "move":
                avail[i] = int(mobile and self.can_move(unit, arg))
            elif kind == "region":
                avail[i] = int(mobile)
            elif kind == "force":
                avail[i] = int(mobile and self._can_hit_force(unit, arg))
            elif kind == "attack":
                t = self.enemies.get(arg)
                if t is not None and t.health > 0:
                    rng = self.unit_shoot_range(agent_id, t)
                    if rng >= 0 and self.distance(unit.pos.x, unit.pos.y, t.pos.x, t.pos.y) <= rng:
                        avail[i] = 1
            elif kind == "ability":
                avail[i] = int(self._ability_available(agent_id, unit, *arg))
        return avail

    def _can_hit_force(self, unit, force: str) -> bool:
        members = self.tracker.members(force)
        if not members:
            return False
        st = self._stats(unit)
        if not st:
            return True
        return any((st.get("range_air", 0) > 0) if m.is_flying else (st.get("range_ground", 0) > 0) for m in members)

    def _ability_available(self, agent_id, unit, k, target) -> bool:
        a = self.abilities[k]
        if a["_type_ids"] and unit.unit_type not in a["_type_ids"]:
            return False
        if a.get("energy") and unit.energy < a["energy"]:
            return False
        if self._ability_cooldown.get((agent_id, k), -1) > self._episode_steps:
            return False
        if target is None:
            return True
        side, idx = target
        t = self.enemies.get(idx) if side == "enemy" else self.agents.get(idx)
        if t is None or t.health <= 0 or (side == "ally" and idx == agent_id):
            return False
        return self.distance(unit.pos.x, unit.pos.y, t.pos.x, t.pos.y) <= float(a.get("range", self.min_shoot_range))

    def get_agent_action(self, a_id, action):
        avail = self.get_avail_agent_actions(a_id)
        assert avail[action] == 1, "Agent {} cannot perform action {} ({})".format(
            a_id, action, self.get_action_names()[action])
        unit = self.agents.get(a_id)
        kind, arg = self.action_layout[action]
        if kind == "noop":
            return None
        tag, x, y = unit.tag, unit.pos.x, unit.pos.y
        if kind == "stop":
            cmd = r_pb.ActionRawUnitCommand(ability_id=ABILITY["stop"], unit_tags=[tag], queue_command=False)
        elif kind == "move":
            m = self._move_amount
            dx, dy = [(0, m), (0, -m), (m, 0), (-m, 0)][arg]
            cmd = r_pb.ActionRawUnitCommand(ability_id=ABILITY["move"], unit_tags=[tag], queue_command=False,
                                            target_world_space_pos=sc_common.Point2D(x=x + dx, y=y + dy))
        elif kind == "region":
            cx, cy = self.spec.regions[arg].center
            cmd = r_pb.ActionRawUnitCommand(ability_id=ABILITY[self.region_action], unit_tags=[tag],
                                            queue_command=False, target_world_space_pos=sc_common.Point2D(x=cx, y=cy))
        elif kind == "force":
            cx, cy = self.tracker.centroid(arg)
            cmd = r_pb.ActionRawUnitCommand(ability_id=ABILITY["attack"], unit_tags=[tag], queue_command=False,
                                            target_world_space_pos=sc_common.Point2D(x=cx, y=cy))
        elif kind == "attack":
            cmd = r_pb.ActionRawUnitCommand(ability_id=ABILITY["attack"], unit_tags=[tag], queue_command=False,
                                            target_unit_tag=self.enemies[arg].tag)
        else:  # ability
            k, target = arg
            a = self.abilities[k]
            if a.get("cooldown_steps"):
                self._ability_cooldown[(a_id, k)] = self._episode_steps + int(a["cooldown_steps"])
            if target is None:
                cmd = r_pb.ActionRawUnitCommand(ability_id=int(a["ability_id"]), unit_tags=[tag], queue_command=False)
            else:
                side, idx = target
                t = self.enemies[idx] if side == "enemy" else self.agents[idx]
                cmd = r_pb.ActionRawUnitCommand(ability_id=int(a["ability_id"]), unit_tags=[tag],
                                                queue_command=False, target_unit_tag=t.tag)
        if self.debug:
            logging.debug("Agent %d: %s", a_id, self.get_action_names()[action])
        return sc_pb.Action(action_raw=r_pb.ActionRaw(unit_command=cmd))

    # ================================================================ launch
    def _launch(self):
        if self.engine == "fake":
            from .fake_sc2 import FakeSC2
            self._sc2_proc = FakeSC2(self.spec, seed=self._seed)
            self._run_config = self._sc2_proc.run_config
            self._controller = self._sc2_proc.controller
        else:
            from pysc2 import maps as pysc2_maps
            from pysc2 import run_configs
            self._run_config = run_configs.get(version=self.game_version)
            _map = pysc2_maps.get(self.map_name)
            interface_options = sc_pb.InterfaceOptions(raw=True, score=False)
            self._sc2_proc = self._run_config.start(window_size=self.window_size, want_rgb=False)
            self._controller = self._sc2_proc.controller
            create = sc_pb.RequestCreateGame(
                local_map=sc_pb.LocalMap(map_path=_map.path, map_data=self._run_config.map_data(_map.path)),
                realtime=False, random_seed=self._seed)
            create.player_setup.add(type=sc_pb.Participant)
            create.player_setup.add(type=sc_pb.Computer, race=races[self._bot_race],
                                    difficulty=difficulties[self.difficulty])
            self._controller.create_game(create)
            self._controller.join_game(sc_pb.RequestJoinGame(race=races[self._agent_race],
                                                             options=interface_options))
        game_info = self._controller.game_info()
        map_info = game_info.start_raw
        p0, p1 = map_info.playable_area.p0, map_info.playable_area.p1
        self.max_distance_x = p1.x - p0.x
        self.max_distance_y = p1.y - p0.y
        self.map_x = map_info.map_size.x
        self.map_y = map_info.map_size.y
        self.pathing_grid = common_utils.process_pathing_grid(
            map_info.pathing_grid.bits_per_pixel, map_info.pathing_grid.data, self.map_x, self.map_y)
        self.terrain_height = common_utils.process_terrain_height(
            map_info.terrain_height.data, self.map_x, self.map_y)
        self._game_ended = False

    # ================================================================= reset
    def reset(self):
        self._episode_steps = 0
        if self._episode_count == 0 and self._controller is None:
            self._launch()
            self._obs = self._controller.observe()
        else:
            self._restart()
        self.death_tracker_ally = np.zeros(self.n_agents)
        self.death_tracker_enemy = np.zeros(self.n_enemies)
        self.previous_ally_units = None
        self.previous_enemy_units = None
        self.win_counted = False
        self.defeat_counted = False
        self._last_outcome = None
        self._ability_cooldown = {}
        self.last_action = np.zeros((self.n_agents, self.n_actions))
        try:
            self.init_units()
        except (protocol.ProtocolError, protocol.ConnectionError):
            self.full_restart()
            self._obs = self._controller.observe()
            self.init_units()
        if self.debug:
            logging.debug("Started Episode {}".format(self._episode_count).center(60, "*"))
        return self.get_obs(), self.get_state()

    def _players(self):
        return (self.spec.ally_player, self.spec.enemy_player)

    def _restart(self):
        """Next round: GameOver maps restart the game; others respawn once both players have no units."""
        try:
            if self._game_ended or self._controller.status == protocol.Status.ended:
                self._controller.restart()
                self._game_ended = False
                self._obs = self._controller.observe()
                return
            players = self._players()
            expected = self.tracker.expected_initial()
            old = {u.tag for u in self._obs.observation.raw_data.units if u.owner in players}
            last_fresh, stable = None, 0
            for _ in range(self.max_reset_tries):
                units = [u for u in self._obs.observation.raw_data.units if u.owner in players]
                # respawned = new tags that some force can take; anything else still alive (old units,
                # broodlings released by dying Zerg structures, hallucinations ...) has to go first
                fresh = [u for u in units if u.tag not in old and self.tracker.matches_force(u)]
                leftovers = [u.tag for u in units if u.tag in old or not self.tracker.matches_force(u)]
                counts: dict[int, int] = {}
                for u in fresh:
                    counts[u.owner] = counts.get(u.owner, 0) + 1
                respawned = bool(fresh) and all(counts.get(p, 0) >= n for p, n in expected.items())
                stable = stable + 1 if fresh and counts == last_fresh else 0
                last_fresh = counts
                if (respawned or stable >= 3) and not leftovers:
                    return            # stable: a binding the game could not spawn; init_units warns
                if leftovers:
                    old.update(leftovers)
                    self._controller.debug([d_pb.DebugCommand(kill_unit=d_pb.DebugKillUnit(tag=leftovers))])
                self._controller.step(2 if not respawned else 1)
                self._obs = self._controller.observe()
            logging.warning("the map did not respawn its units after %d tries; restarting SC2", self.max_reset_tries)
        except (protocol.ProtocolError, protocol.ConnectionError):
            pass
        self.full_restart()
        self._obs = self._controller.observe()

    def init_units(self):
        """Wait until the round's units exist, then fill the slots."""
        expected = self.tracker.expected_initial()
        players = self._players()
        last, stable = None, 0
        for _ in range(40):
            counts = {}
            for u in self._obs.observation.raw_data.units:
                if u.owner in players and self.tracker.matches_force(u):
                    counts[u.owner] = counts.get(u.owner, 0) + 1
            if all(counts.get(p, 0) >= n for p, n in expected.items()):
                break
            stable = stable + 1 if counts == last and counts else 0
            if stable >= 3:      # e.g. a binding the game cannot spawn: go on with what is there
                logging.warning("expected %s units per player at round start, found %s", expected, counts)
                break
            last = counts
            self._controller.step(1)
            self._obs = self._controller.observe()
        loop0 = self._obs.observation.game_loop
        self.tracker.reset(loop0)
        self.tracker.observe(self._obs.observation.raw_data.units, loop0)
        if self.plan is not None:
            self.plan.reset(loop0)
            self.plan.update(self._obs.observation.raw_data.units, loop0)
        self._sync_units()
        if not self._max_reward_ready:
            hp = sum(s.unit.health_max + s.unit.shield_max for s in self.tracker.slots("enemy") if s.present)
            self.max_reward = self.n_enemies * self.reward_death_value + self.reward_win + hp
            self._max_reward_ready = True
        self._prev_hp = self._hp_snapshot()
        self._unit_types = [u.unit_type for u in self.agents.values() if u is not None] + \
                           [u.unit_type for u in self.enemies.values() if u is not None]

    def _sync_units(self):
        """agents / ally_assets / enemies dicts: slot index -> raw unit (None if not alive)."""
        self.agents = {s.index: s.unit if s.present else None for s in self.tracker.slots("agent")}
        self.ally_assets = {s.index: s.unit if s.present else None for s in self.tracker.slots("ally_asset")}
        self.enemies = {s.index: s.unit if s.present else None for s in self.tracker.slots("enemy")}

    def _hp_snapshot(self):
        out = {}
        for group in ("agent", "ally_asset", "enemy"):
            for s in self.tracker.slots(group):
                if s.present:
                    out[(group, s.index)] = s.unit.health + s.unit.shield
        return out

    # ================================================================== step
    def step(self, actions):
        actions_int = [int(a) for a in actions]
        self.last_action = np.eye(self.n_actions)[np.array(actions_int)]
        sc_actions = []
        for a_id, action in enumerate(actions_int):
            sc_action = self.get_agent_action(a_id, action)
            if sc_action:
                sc_actions.append(sc_action)
        try:
            if self._controller.status != protocol.Status.in_game:
                self.full_restart()
                self._obs = self._controller.observe()
                return self._pack_reward(0.0), True, {"battle_won": False, "restart": True}
            self._controller.actions(sc_pb.RequestAction(actions=sc_actions))
            self._controller.step(self._step_mul)
            self._obs = self._controller.observe()
        except (protocol.ProtocolError, protocol.ConnectionError):
            self.full_restart()
            self._obs = self._controller.observe()
            return self._pack_reward(0.0), True, {"battle_won": False, "restart": True}

        self._total_steps += 1
        self._episode_steps += 1
        units = self._obs.observation.raw_data.units
        events = self.tracker.observe(units, self._obs.observation.game_loop)
        plan_info = self.plan.update(units, self._obs.observation.game_loop) if self.plan is not None else None
        self._sync_units()

        reward = self.reward_battle()
        if plan_info and self.reward_phase and not self.reward_sparse:
            reward += self.reward_phase * sum(1 for p in plan_info["entered"] if not self.plan.is_terminal(p))
        game_end_code = self._outcome()

        info = {"battle_won": False,
                "dead_allies": sum(1 for s in self.tracker.slots("agent") if s.filled and not s.alive),
                "dead_enemies": sum(1 for s in self.tracker.slots("enemy") if s.filled and not s.alive)}
        detail = {"events": events, "outcome": None}
        if plan_info is not None:
            detail["plan_phases"] = self.plan.active_phases()
            detail["plan_fired"] = plan_info["fired"]
        terminated = False
        if game_end_code is not None:
            terminated = True
            self.battles_game += 1
            detail["outcome"] = {1: "success", -1: "failure", 0: "draw"}[game_end_code]
            info["battle_lost"] = int(game_end_code == -1)
            if game_end_code == 1 and not self.win_counted:
                self.battles_won += 1
                self.win_counted = True
                info["battle_won"] = True
                reward = 1 if self.reward_sparse else reward + self.reward_win
            elif game_end_code == -1 and not self.defeat_counted:
                self.defeat_counted = True
                reward = -1 if self.reward_sparse else reward + self.reward_defeat
        elif self._episode_steps >= self.episode_limit:
            terminated = True
            if self.continuing_episode:
                info["episode_limit"] = True
            self.battles_game += 1
            self.timeouts += 1
            detail["outcome"] = "timeout"
        if terminated:
            self._episode_count += 1
        self.last_detail = detail
        if self.info_detail:
            info.update(detail)
        if self.reward_scale and not self.reward_sparse:
            reward /= self.max_reward / self.reward_scale_rate
        self.reward = reward
        return self._pack_reward(reward), terminated, info

    def _pack_reward(self, reward):
        if self.reward_tuple:
            return (reward, self.delta_enemy, self.delta_deaths, self.delta_ally)
        return reward

    def _outcome(self) -> Optional[int]:
        """1 win, -1 loss, 0 draw, None running."""
        # a --gameover map ends the game itself
        if self._obs.player_result:
            self._game_ended = True
            for pr in self._obs.player_result:
                if pr.player_id == self.spec.ally_player:
                    return PLAYER_RESULT.get(pr.result, 0)
            return 0
        if self.termination == "plan":
            out = self.plan.outcome
            if out:
                return 1 if out == 1 else -1
        elif self.termination == "intent":
            succ = conditions.truth(self.spec.intent.get("success"), self.tracker, self.spec.derived)
            fail = conditions.truth(self.spec.intent.get("failure"), self.tracker, self.spec.derived)
            if fail is True and (self.failure_first or succ is not True):
                return -1
            if succ is True:
                return 1
        else:  # army
            ally = sum(s.present for s in self.tracker.slots("agent"))
            enemy = sum(s.present for s in self.tracker.slots("enemy"))
            if ally and not enemy:
                return 1
            if enemy and not ally:
                return -1
            if not ally and not enemy:
                return 0
        if self.defeat_on_army_loss:
            agents = self.tracker.slots("agent")
            waiting = any(not s.filled for s in agents
                          if not self.spec.force_by_name[s.force].initial)
            if agents and not any(s.present for s in agents) and not waiting:
                return -1
        return None

    def update_units(self):            # sc2te API compatibility
        self.tracker.observe(self._obs.observation.raw_data.units, self._obs.observation.game_loop)
        self._sync_units()
        return self._outcome()

    # ================================================================ reward
    def reward_battle(self):
        if self.reward_sparse:
            self.delta_enemy = self.delta_deaths = self.delta_ally = 0
            return 0
        neg = self.reward_negative_scale
        delta_enemy = delta_deaths = delta_ally = 0.0
        prev = self._prev_hp
        for s in self.tracker.slots("enemy"):
            key = ("enemy", s.index)
            if key not in prev:
                continue                     # not alive in the previous step (or spawned just now)
            if s.present:
                delta_enemy += max(0.0, prev[key] - s.unit.health - s.unit.shield)
            else:
                delta_enemy += prev[key]
                delta_deaths += self.reward_death_value
                self.death_tracker_enemy[s.index] = 1
        for group in ("agent", "ally_asset"):
            for s in self.tracker.slots(group):
                key = (group, s.index)
                if key not in prev:
                    continue
                if s.present:
                    delta_ally += neg * max(0.0, prev[key] - s.unit.health - s.unit.shield)
                else:
                    delta_ally += neg * prev[key]
                    if not self.reward_only_positive:
                        delta_deaths -= self.reward_death_value * neg
                    if group == "agent":
                        self.death_tracker_ally[s.index] = 1
        self._prev_hp = self._hp_snapshot()
        self.delta_enemy, self.delta_deaths, self.delta_ally = delta_enemy, delta_deaths, delta_ally
        if self.reward_only_positive:
            return abs(delta_enemy + delta_deaths)
        return delta_enemy + delta_deaths - delta_ally

    # ===================================================== unit type one-hot
    def get_unit_type_id(self, unit, ally):
        return self.spec.type_index(unit.unit_type)

    def _type_bits(self, unit, out, offset):
        if self.unit_type_bits:
            i = self.spec.type_index(unit.unit_type)
            if i >= 0:
                out[offset + i] = 1

    # =========================================================== observations
    def _ally_rows(self, agent_id):
        """(kind, index, unit) of the other agents, then the allied assets."""
        rows = [("agent", i, self.agents.get(i)) for i in range(self.n_agents) if i != agent_id]
        rows += [("ally_asset", i, self.ally_assets.get(i)) for i in range(self.n_ally_assets)]
        return rows

    def get_obs_enemy_feats_size(self):
        nf = 4 + self.unit_type_bits
        if self.obs_all_health:
            nf += 1 + self.shield_bits_enemy
        return self.n_enemies, nf

    def get_obs_ally_feats_size(self):
        nf = 4 + self.unit_type_bits
        if self.obs_all_health:
            nf += 1 + self.shield_bits_ally
        if self.obs_last_action:
            nf += self.n_actions
        return self.n_agents - 1 + self.n_ally_assets, nf

    def get_obs_own_feats_size(self):
        own = self.unit_type_bits
        if self.obs_own_health:
            own += 1 + self.shield_bits_ally
        if self.obs_own_position:
            own += 2
        if self.obs_timestep_number:
            own += 1
        return own

    def get_obs_region_feats_size(self):
        return (self.n_regions, 3) if self.obs_regions else (0, 3)

    def get_obs_size(self):
        n_e, f_e = self.get_obs_enemy_feats_size()
        n_a, f_a = self.get_obs_ally_feats_size()
        n_r, f_r = self.get_obs_region_feats_size()
        size = self.get_obs_move_feats_size() + n_e * f_e + n_a * f_a + n_r * f_r + self.get_obs_own_feats_size()
        if self.obs_plan_phase:
            size += self.n_phases
        return size

    def get_obs_agent(self, agent_id):
        unit = self.agents.get(agent_id)
        move_feats = np.zeros(self.get_obs_move_feats_size(), dtype=np.float32)
        n_e, f_e = self.get_obs_enemy_feats_size()
        n_a, f_a = self.get_obs_ally_feats_size()
        n_r, f_r = self.get_obs_region_feats_size()
        enemy_feats = np.zeros((n_e, f_e), dtype=np.float32)
        ally_feats = np.zeros((n_a, f_a), dtype=np.float32)
        region_feats = np.zeros((n_r, f_r), dtype=np.float32)
        own_feats = np.zeros(self.get_obs_own_feats_size(), dtype=np.float32)

        if unit is not None and unit.health > 0:
            x, y = unit.pos.x, unit.pos.y
            sight = self.unit_sight_range(agent_id)
            avail = self.get_avail_agent_actions(agent_id)
            for m in range(self.n_actions_move):
                move_feats[m] = avail[m + 2]
            ind = self.n_actions_move
            if self.obs_pathing_grid:
                move_feats[ind:ind + self.n_obs_pathing] = self.get_surrounding_pathing(unit)
                ind += self.n_obs_pathing
            if self.obs_terrain_height:
                move_feats[ind:] = self.get_surrounding_height(unit)

            for e_id in range(self.n_enemies):
                e = self.enemies.get(e_id)
                if e is None or e.health <= 0:
                    continue
                dist = self.distance(x, y, e.pos.x, e.pos.y)
                if dist >= sight:
                    continue
                enemy_feats[e_id, 0] = avail[self.n_actions_no_attack + e_id]
                enemy_feats[e_id, 1] = dist / sight
                enemy_feats[e_id, 2] = (e.pos.x - x) / sight
                enemy_feats[e_id, 3] = (e.pos.y - y) / sight
                ind = 4
                if self.obs_all_health:
                    enemy_feats[e_id, ind] = e.health / e.health_max if e.health_max else 0
                    ind += 1
                    if self.shield_bits_enemy:
                        enemy_feats[e_id, ind] = e.shield / e.shield_max if e.shield_max else 0
                        ind += 1
                self._type_bits(e, enemy_feats[e_id], ind)

            for i, (kind, idx, a) in enumerate(self._ally_rows(agent_id)):
                if a is None or a.health <= 0:
                    continue
                dist = self.distance(x, y, a.pos.x, a.pos.y)
                if dist >= sight:
                    continue
                ally_feats[i, 0] = 1
                ally_feats[i, 1] = dist / sight
                ally_feats[i, 2] = (a.pos.x - x) / sight
                ally_feats[i, 3] = (a.pos.y - y) / sight
                ind = 4
                if self.obs_all_health:
                    ally_feats[i, ind] = a.health / a.health_max if a.health_max else 0
                    ind += 1
                    if self.shield_bits_ally:
                        ally_feats[i, ind] = a.shield / a.shield_max if a.shield_max else 0
                        ind += 1
                self._type_bits(a, ally_feats[i], ind)
                ind += self.unit_type_bits
                if self.obs_last_action and kind == "agent":
                    ally_feats[i, ind:] = self.last_action[idx]

            if self.obs_regions:
                scale = max(self.max_distance_x, self.max_distance_y) or 1.0
                for r_id, r in enumerate(self.spec.regions):
                    region_feats[r_id, 0] = (r.center[0] - x) / scale
                    region_feats[r_id, 1] = (r.center[1] - y) / scale
                    region_feats[r_id, 2] = 1.0 if r.contains(x, y) else 0.0

            ind = 0
            if self.obs_own_health:
                own_feats[ind] = unit.health / unit.health_max if unit.health_max else 0
                ind += 1
                if self.shield_bits_ally:
                    own_feats[ind] = unit.shield / unit.shield_max if unit.shield_max else 0
                    ind += 1
            if self.obs_own_position:
                own_feats[ind] = x / self.map_x if self.map_x else 0
                own_feats[ind + 1] = y / self.map_y if self.map_y else 0
                ind += 2
            self._type_bits(unit, own_feats, ind)
            ind += self.unit_type_bits

        if self.obs_timestep_number:
            own_feats[-1] = self._episode_steps / self.episode_limit
        parts = [move_feats.flatten(), enemy_feats.flatten(), ally_feats.flatten(), region_feats.flatten(),
                 own_feats.flatten()]
        if self.obs_plan_phase:
            parts.append(np.asarray(self.plan.one_hot(), dtype=np.float32))
        return np.concatenate(parts)

    def get_obs(self):
        return [self.get_obs_agent(i) for i in range(self.n_agents)]

    # ================================================================= state
    def get_state_size(self):
        if self.obs_instead_of_state:
            return self.get_obs_size() * self.n_agents
        nf_al = 4 + self.shield_bits_ally + self.unit_type_bits
        nf_en = 3 + self.shield_bits_enemy + self.unit_type_bits
        size = (self.n_agents + self.n_ally_assets) * nf_al + self.n_enemies * nf_en
        if self.state_last_action:
            size += self.n_agents * self.n_actions
        if self.state_timestep_number:
            size += 1
        if self.state_plan_phase:
            size += self.n_phases
        return size

    def get_state_dict(self):
        nf_al = 4 + self.shield_bits_ally + self.unit_type_bits
        nf_en = 3 + self.shield_bits_enemy + self.unit_type_bits
        ally_state = np.zeros((self.n_agents + self.n_ally_assets, nf_al))
        enemy_state = np.zeros((self.n_enemies, nf_en))
        cx, cy = self.map_x / 2, self.map_y / 2
        mx, my = self.max_distance_x or 1, self.max_distance_y or 1
        rows = [self.agents.get(i) for i in range(self.n_agents)] + \
               [self.ally_assets.get(i) for i in range(self.n_ally_assets)]
        for i, u in enumerate(rows):
            if u is None or u.health <= 0:
                continue
            ally_state[i, 0] = u.health / u.health_max if u.health_max else 0
            if u.energy_max and not u.weapon_cooldown:
                ally_state[i, 1] = u.energy / u.energy_max
            else:
                ally_state[i, 1] = min(1.0, u.weapon_cooldown / 30.0)
            ally_state[i, 2] = (u.pos.x - cx) / mx
            ally_state[i, 3] = (u.pos.y - cy) / my
            ind = 4
            if self.shield_bits_ally:
                ally_state[i, ind] = u.shield / u.shield_max if u.shield_max else 0
                ind += 1
            self._type_bits(u, ally_state[i], ind)
        for e_id in range(self.n_enemies):
            e = self.enemies.get(e_id)
            if e is None or e.health <= 0:
                continue
            enemy_state[e_id, 0] = e.health / e.health_max if e.health_max else 0
            enemy_state[e_id, 1] = (e.pos.x - cx) / mx
            enemy_state[e_id, 2] = (e.pos.y - cy) / my
            ind = 3
            if self.shield_bits_enemy:
                enemy_state[e_id, ind] = e.shield / e.shield_max if e.shield_max else 0
                ind += 1
            self._type_bits(e, enemy_state[e_id], ind)
        state = {"allies": ally_state, "enemies": enemy_state}
        if self.state_last_action:
            state["last_action"] = self.last_action
        if self.state_timestep_number:
            state["timestep"] = self._episode_steps / self.episode_limit
        if self.state_plan_phase:
            state["plan_phase"] = np.asarray(self.plan.one_hot(), dtype=np.float32)
        return state

    def get_state(self):
        if self.obs_instead_of_state:
            return np.concatenate(self.get_obs(), axis=0).astype(np.float32)
        d = self.get_state_dict()
        parts = [d["allies"].flatten(), d["enemies"].flatten()]
        if "last_action" in d:
            parts.append(d["last_action"].flatten())
        if "timestep" in d:
            parts.append(np.array([d["timestep"]]))
        if "plan_phase" in d:
            parts.append(d["plan_phase"])
        return np.concatenate(parts).astype(np.float32)

    def get_visibility_matrix(self):
        arr = np.zeros((self.n_agents, self.n_agents + self.n_enemies), dtype=bool)
        for i in range(self.n_agents):
            u = self.agents.get(i)
            if u is None or u.health <= 0:
                continue
            sight = self.unit_sight_range(i)
            for j in range(self.n_agents):
                a = self.agents.get(j)
                if j != i and a is not None and a.health > 0 and \
                        self.distance(u.pos.x, u.pos.y, a.pos.x, a.pos.y) < sight:
                    arr[i, j] = True
            for e_id in range(self.n_enemies):
                e = self.enemies.get(e_id)
                if e is not None and e.health > 0 and self.distance(u.pos.x, u.pos.y, e.pos.x, e.pos.y) < sight:
                    arr[i, self.n_agents + e_id] = True
        return arr

    # ================================================================== misc
    def get_unit_by_id(self, a_id):
        return self.agents.get(a_id)

    def get_env_info(self):
        info = super().get_env_info()
        info.update({"n_enemies": self.n_enemies, "n_ally_assets": self.n_ally_assets,
                     "n_regions": self.n_regions, "action_names": self.get_action_names(),
                     "unit_families": list(self.spec.families), "regions": [r.name for r in self.spec.regions],
                     "phases": list(self.spec.phase_ids) if self.plan is not None else []})
        # keys pymarl2 / wqmix / QPLEX-style forks read from SMAC's env_info
        nf_al = 4 + self.shield_bits_ally + self.unit_type_bits
        nf_en = 3 + self.shield_bits_enemy + self.unit_type_bits
        info.update({
            "unit_dim": nf_al,                         # one ally row of the state; agents come first
            "n_allies": self.n_agents - 1 + self.n_ally_assets,
            "state_ally_feats_size": nf_al,
            "state_enemy_feats_size": nf_en,
            "obs_component": self.get_obs_component(),
            "state_component": self.get_state_component(),
            "map_type": "stratagem",
        })
        return info

    def get_obs_component(self):
        """Sizes of the obs blocks in order (move, enemies, allies, regions, own[, plan phase])."""
        comp = [self.get_obs_move_feats_size(), self.get_obs_enemy_feats_size(), self.get_obs_ally_feats_size(),
                self.get_obs_region_feats_size(), self.get_obs_own_feats_size()]
        if self.obs_plan_phase:
            comp.append(self.n_phases)
        return comp

    def get_state_component(self):
        """Sizes of the state blocks in order (allies + ally assets, enemies[, last action, timestep, phase])."""
        nf_al = 4 + self.shield_bits_ally + self.unit_type_bits
        nf_en = 3 + self.shield_bits_enemy + self.unit_type_bits
        comp = [(self.n_agents + self.n_ally_assets) * nf_al, self.n_enemies * nf_en]
        if self.state_last_action:
            comp.append(self.n_agents * self.n_actions)
        if self.state_timestep_number:
            comp.append(1)
        if self.state_plan_phase:
            comp.append(self.n_phases)
        return comp

    def get_stats(self):
        return {"battles_won": self.battles_won, "battles_game": self.battles_game,
                "battles_draw": self.timeouts,
                "win_rate": self.battles_won / self.battles_game if self.battles_game else 0.0,
                "timeouts": self.timeouts, "restarts": self.force_restarts}

    def describe(self) -> str:
        return self.spec.describe()

    def close(self):
        if self.renderer is not None:
            self.renderer.close()
            self.renderer = None
        if self._sc2_proc:
            self._sc2_proc.close()
            self._sc2_proc = None
            self._controller = None

    def full_restart(self):
        if self._sc2_proc:
            self._sc2_proc.close()
        self._launch()
        self.force_restarts += 1
